// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

import java.util.List;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

/**
 * Unit spec for runtime cost calibration — the engine learning, from its own executions, how many nanoseconds one unit
 * of predicted work costs for each strategy on the machine it is running on.
 * <p>
 * The arithmetic is the easy part. What these tests are really for is the safety properties, because this component
 * feeds itself: it learns from the decisions it influences. Three of them matter most.
 * <ul>
 * <li>Cold start must be inert — before anything is measured, dispatch must behave exactly as it did.
 * <li>Thin evidence must not decide — an estimate from two samples must produce an interval too wide to dominate.
 * <li>Certainty must not outrun the estimate — the moving average keeps tracking change forever, so the confidence
 * interval must stop narrowing rather than claim precision about a quantity that is still moving.
 * </ul>
 */
public class LmdbNativeCostCalibrationTest {

	private static final String FAST = LmdbNativeAttemptMetrics.PATH_IR_AGGREGATE;
	private static final String SLOW = LmdbNativeAttemptMetrics.PATH_NESTED_LOOP;

	@BeforeEach
	public void setUp() {
		LmdbNativeCostCalibration.reset();
		// Consumption is opt-in in production, precisely so that dispatch stays reproducible by default; these tests
		// are about what happens once it is switched on.
		System.setProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY, "true");
	}

	@AfterEach
	public void tearDown() {
		LmdbNativeCostCalibration.reset();
		System.clearProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY);
		System.clearProperty(LmdbNativeCostCalibration.EXPLORATION_PROPERTY);
	}

	private static void observe(String tag, double nanosPerUnit, int times) {
		for (int i = 0; i < times; i++) {
			LmdbNativeCostCalibration.record(tag, 10_000d, (long) (nanosPerUnit * 10_000d));
		}
	}

	// ---------------------------------------------------------------- learning

	@Test
	public void learnsNanosPerWorkUnitFromExecutions() {
		observe(FAST, 5d, 40);

		assertThat(LmdbNativeCostCalibration.nanosPerWorkUnit(FAST)).isCloseTo(5d, within(0.5d));
		assertThat(LmdbNativeCostCalibration.observations(FAST)).isEqualTo(40L);
	}

	@Test
	public void tracksAChangeInMachineSpeed() {
		observe(FAST, 5d, 60);
		double before = LmdbNativeCostCalibration.nanosPerWorkUnit(FAST);
		// The machine gets slower -- another process arrives, or the JVM deoptimizes.
		observe(FAST, 50d, 60);

		assertThat(LmdbNativeCostCalibration.nanosPerWorkUnit(FAST))
				.as("a moving average must follow a genuine change rather than averaging it away forever")
				.isGreaterThan(before * 3d);
	}

	@Test
	public void oneOutlierCannotMoveTheEstimateFar() {
		observe(FAST, 5d, 50);
		double before = LmdbNativeCostCalibration.nanosPerWorkUnit(FAST);
		// A GC pause during one measurement.
		LmdbNativeCostCalibration.record(FAST, 10_000d, (long) (500d * 10_000d));

		assertThat(LmdbNativeCostCalibration.nanosPerWorkUnit(FAST))
				.as("smoothing must absorb a single bad sample")
				.isLessThan(before * 3d);
	}

	@Test
	public void implausibleAndTinySamplesAreDiscarded() {
		LmdbNativeCostCalibration.record(FAST, 1d, 1_000_000L); // below MIN_WORK: dominated by fixed overhead
		LmdbNativeCostCalibration.record(FAST, 10_000d, Long.MAX_VALUE); // implausible nanos-per-unit
		LmdbNativeCostCalibration.record(FAST, Double.NaN, 1_000L);
		LmdbNativeCostCalibration.record(FAST, 10_000d, 0L);

		assertThat(LmdbNativeCostCalibration.observations(FAST)).isZero();
	}

	// ---------------------------------------------------------------- safety

	@Test
	public void coldStartIsInert() {
		LmdbNativeWork work = LmdbNativeWork.exact(1_000d);

		assertThat(LmdbNativeCostCalibration.toTime(FAST, work))
				.as("before anything is measured, dispatch must behave exactly as it did")
				.isEqualTo(work);
	}

	@Test
	public void thinEvidenceProducesAnIntervalTooWideToDecide() {
		observe(FAST, 1d, 2);
		observe(SLOW, 2d, 2);

		LmdbNativeWork fast = LmdbNativeCostCalibration.toTime(FAST, LmdbNativeWork.exact(1_000d));
		LmdbNativeWork slow = LmdbNativeCostCalibration.toTime(SLOW, LmdbNativeWork.exact(1_000d));

		assertThat(fast.beats(slow))
				.as("two samples is not enough to overrule the specialization order, even when the means differ")
				.isFalse();
	}

	@Test
	public void ampleEvidenceOfALargeDifferenceDoesDecide() {
		observe(FAST, 1d, 200);
		observe(SLOW, 20d, 200);

		LmdbNativeWork fast = LmdbNativeCostCalibration.toTime(FAST, LmdbNativeWork.exact(1_000d));
		LmdbNativeWork slow = LmdbNativeCostCalibration.toTime(SLOW, LmdbNativeWork.exact(1_000d));

		assertThat(fast.beats(slow))
				.as("a twentyfold difference backed by two hundred samples is worth acting on")
				.isTrue();
	}

	@Test
	public void certaintyStopsGrowingBecauseTheEstimateKeepsMoving() {
		observe(FAST, 5d, 100);
		double narrowAt100 = width(LmdbNativeCostCalibration.toTime(FAST, LmdbNativeWork.exact(1_000d)));
		observe(FAST, 5d, 100_000);
		double narrowAtMany = width(LmdbNativeCostCalibration.toTime(FAST, LmdbNativeWork.exact(1_000d)));

		assertThat(narrowAtMany)
				.as("the moving average never stops tracking change, so the interval must stop claiming it knows "
						+ "better; otherwise the model asserts precision about a quantity it lets drift")
				.isCloseTo(narrowAt100, within(narrowAt100 * 0.05d));
	}

	private static double width(LmdbNativeWork work) {
		return work.high() - work.low();
	}

	@Test
	public void disablingRevertsToRawWork() {
		observe(FAST, 100d, 200);
		System.setProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY, "false");

		LmdbNativeWork work = LmdbNativeWork.exact(1_000d);
		assertThat(LmdbNativeCostCalibration.toTime(FAST, work)).isEqualTo(work);
	}

	/**
	 * Both readers of {@code rdf4j.lmdb.costCalibration.enabled} — this legacy scalar path and the adaptive model — now
	 * agree with the runtime-property registry on a default-ON polarity (bug B3: this reader previously used opt-in
	 * {@code Boolean.getBoolean}, so the same property carried opposite defaults in two places). Opting out remains a
	 * single explicit {@code false}.
	 */
	@Test
	public void calibrationDefaultOnMatchesTheAdaptiveModelAndRegistry() {
		System.clearProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY);
		observe(FAST, 1d, 200);

		assertThat(LmdbNativeCostCalibration.enabled())
				.as("the legacy reader now shares the registry's default-on polarity (B3)")
				.isTrue();
		System.setProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY, "false");
		assertThat(LmdbNativeCostCalibration.enabled())
				.as("opting out remains one explicit property away")
				.isFalse();
		LmdbNativeWork work = LmdbNativeWork.exact(1_000d);
		assertThat(LmdbNativeCostCalibration.toTime(FAST, work))
				.as("recorded samples remain inert while calibration consumption is off")
				.isEqualTo(work);
	}

	@Test
	public void recordingContinuesEvenWhileConsumptionIsOff() {
		System.setProperty(LmdbNativeCostCalibration.ENABLED_PROPERTY, "false");
		observe(FAST, 7d, 30);

		assertThat(LmdbNativeCostCalibration.observations(FAST))
				.as("evidence accumulates regardless, so switching consumption back on does not start from cold")
				.isEqualTo(30L);
	}

	@Test
	public void unknownWorkStaysUnknown() {
		observe(FAST, 5d, 200);

		assertThat(LmdbNativeCostCalibration.toTime(FAST, LmdbNativeWork.UNKNOWN))
				.as("calibration converts a cost; it cannot manufacture one")
				.isEqualTo(LmdbNativeWork.UNKNOWN);
	}

	// ---------------------------------------------------------------- feedback into dispatch

	@Test
	public void measurementCanOverruleEqualPredictedWork() {
		// Two strategies the model prices identically. Only measurement can tell them apart -- and this is exactly
		// the case the cost model could not express before: same work, different speed per unit.
		observe(FAST, 1d, 200);
		observe(SLOW, 30d, 200);

		List<LmdbNativeStrategyProposal<String>> candidates = List.of(
				new LmdbNativeStrategyProposal<>(() -> FAST, LmdbNativeWork.exact(1_000d), FAST, () -> {
				}),
				new LmdbNativeStrategyProposal<>(() -> SLOW, LmdbNativeWork.exact(1_000d), SLOW, () -> {
				}));

		assertThat(candidates.get(LmdbNativeStrategyArbiter.rank(candidates)).tag)
				.as("identical predicted work, thirtyfold measured difference: the measurement decides")
				.isEqualTo(FAST);
	}

	@Test
	public void explorationIsOptInAndBounded() {
		assertThat(LmdbNativeCostCalibration.explorationEnabled())
				.as("a user query must not pay for a randomly selected rival unless exploration is explicitly enabled")
				.isFalse();

		System.setProperty(LmdbNativeCostCalibration.EXPLORATION_PROPERTY, "true");
		assertThat(LmdbNativeCostCalibration.explorationEnabled()).isTrue();

		observe(FAST, 5d, 500);
		assertThat(LmdbNativeCostCalibration.shouldExplore(FAST))
				.as("a well-measured strategy is never explored -- there is nothing left to learn")
				.isFalse();

		System.clearProperty(LmdbNativeCostCalibration.EXPLORATION_PROPERTY);
		assertThat(LmdbNativeCostCalibration.explorationEnabled())
				.as("removing the opt-in restores fully reproducible dispatch")
				.isFalse();
	}
}
